// Models: the WASM module against the native runtime, bit for bit.
//
// Every model of the corpus is compiled by the native ipc and generated by
// the native ipgen (--dump prints each float as its binary32 bits and each
// image as an FNV-1a 64 hash) and by the WASM module, for several seeds and
// inputs. Two compilers and two architectures must agree on every vertex,
// index, material number, texture and counter. A texture also equals what
// the 2D `generate` of the same module makes of the skin's own program, and
// failures carry the same reason, stage and message on both sides.
"use strict";

const assert = require("node:assert/strict");
const { spawnSync } = require("node:child_process");
const crypto = require("node:crypto");
const fs = require("node:fs");
const os = require("node:os");
const path = require("node:path");

const repo = path.resolve(__dirname, "../../..");
// Error tags of the C API (iprop.h).
const E_FORMAT = 2, E_TRAP = 3, STAGE_LOAD = 1, STAGE_EXECUTE = 4;
const REASON = { badMagic: 1002, numericRange: 3010, workExhausted: 3015, cancelled: 3016 };

const corpus = [
    { name: "primitives", source: "backends/html5/test/fixtures/model-primitives.ips", seeds: [0, 1, 2, 7, 26, 4294967295],
      uniforms: [{}, { stretch: 1.75, sides: 5, tint: "#c0392b" }, { stretch: 0.625, sides: 31, rounding: 2.5 }] },
    { name: "crate", source: "backends/capi3d/test/crate.ips", seeds: [0, 5, 77],
      uniforms: [{}, { wide: 6.5, extra: 0 }, { wide: 11.75, stain: "#10a0f080" }] },
    { name: "chair", source: "examples/models/chair.ips", seeds: [0, 1, 2, 3, 4, 5, 9, 13],
      uniforms: [{}, { finish: 5, fabric: 2 }] },
    { name: "empty", source: "backends/capi3d/test/empty.ips", seeds: [0, 9], uniforms: [{}] },
    // Material maps, glass and windows (M2): numbers, alpha modes and maps.
    { name: "materials", source: "tests/model/corpus/materials.ips", seeds: [1, 3, 6], uniforms: [{}] },
    // Shapes along a path, shaping blocks, outputs and parts (M3).
    { name: "shapes", source: "tests/model/corpus/shapes.ips", seeds: [1, 2, 3, 5, 8], uniforms: [{}] },
    { name: "model-parts", source: "examples/language/model-parts.ips", seeds: [1, 9], uniforms: [{}] },
];

function fnv1a64(bytes) {
    let state = 0xcbf29ce484222325n;
    for (const byte of bytes) state = ((state ^ BigInt(byte)) * 0x100000001b3n) & 0xffffffffffffffffn;
    return state.toString(16).padStart(16, "0");
}

const bits = array => Array.from(new Uint32Array(array.buffer, array.byteOffset, array.length));
const bitsOf = value => new Uint32Array(new Float32Array([value]).buffer)[0];

// The outputs of a WASM result in the shape of `ipgen --dump` (M3).
function dumpedOutputs(result) {
    return result.outputs.map(output => {
        const entry = { name: output.name, kind: output.kind, list: output.list };
        const values = bits(output.values), triple = at => values.slice(at, at + 3);
        if (output.kind === "box3d") {
            entry.boxes = [];
            for (let i = 0; i < output.count; ++i)
                entry.boxes.push({ center: triple(i * 15), size: triple(i * 15 + 3),
                    axes: [triple(i * 15 + 6), triple(i * 15 + 9), triple(i * 15 + 12)] });
        } else {
            entry.points = [];
            for (let i = 0; i < output.count; ++i) entry.points.push(triple(i * 3));
        }
        return entry;
    });
}

// A WASM result in the shape of `ipgen --dump`.
function dumped(result, seed) {
    const dump = dumpedCore(result, seed);
    if (result.outputs.length) dump.outputs = dumpedOutputs(result);
    return dump;
}

function dumpedCore(result, seed) {
    return {
        seed,
        size: result.size.map(bitsOf),
        units_per_meter: bitsOf(result.unitsPerMeter),
        bounds: { min: result.bounds.min.map(bitsOf), max: result.bounds.max.map(bitsOf) },
        vertices: result.vertexCount,
        triangles: result.triangleCount,
        fuel: { budget: result.fuel.budget, spent: result.fuel.used },
        work: { budget: result.work.budget, spent: result.work.used },
        textures: result.textures.map(texture => ({
            key: texture.key, name: texture.name, width: texture.width, height: texture.height,
            asset: [texture.assetWidth, texture.assetHeight], repeats: texture.repeats,
            color: fnv1a64(texture.data),
            images: texture.images.map(image => ({ kind: image.kind, name: image.name, pixels: fnv1a64(image.data) })),
        })),
        surfaces: result.surfaces.map(surface => ({
            texture: surface.texture, roughness: bitsOf(surface.roughness), metallic: bitsOf(surface.metallic),
            emission: bitsOf(surface.emission), alpha: surface.alphaMode, cutoff: bitsOf(surface.alphaCutoff),
            two_sided: surface.twoSided, crisp: surface.crisp,
            positions: bits(surface.positions), normals: bits(surface.normals), tangents: bits(surface.tangents),
            uvs: bits(surface.uvs), indices: Array.from(surface.indices),
        })),
    };
}

// The pinned corpus (tests/fixtures/model-corpus-v1.2.json, written by
// tests/model/corpus_test.cpp): the lines of one case, made from the WASM
// result in the exact form the native test writes them.
const sha256 = bytes => "sha256:" + crypto.createHash("sha256").update(bytes).digest("hex");
const bytesOf = array => Buffer.from(array.buffer, array.byteOffset, array.byteLength);
function corpusPins(program, result) {
    const triple = values => values.map(bitsOf).join(",");
    const lines = ["program " + sha256(program),
        "vertices " + result.vertexCount + " triangles " + result.triangleCount + " fuel " + result.fuel.used + "/" +
            result.fuel.budget + " work " + result.work.used + "/" + result.work.budget,
        "size " + triple(result.size) + " units " + bitsOf(result.unitsPerMeter) + " bounds " + triple(result.bounds.min) +
            " " + triple(result.bounds.max)];
    result.textures.forEach((texture, t) => {
        lines.push("texture " + t + " " + texture.name + " " + texture.key + " " + texture.width + "x" + texture.height + " of " +
            texture.assetWidth + "x" + texture.assetHeight + (texture.repeats ? " repeats" : " clamps") + " " + sha256(texture.data));
        texture.images.forEach((image, i) => lines.push("texture " + t + " image " + i + " kind " + image.kind + " " + image.name +
            " " + sha256(image.data)));
    });
    result.surfaces.forEach((surface, s) => {
        lines.push("surface " + s + " texture " + surface.texture + " roughness " + bitsOf(surface.roughness) + " metallic " +
            bitsOf(surface.metallic) + " emission " + bitsOf(surface.emission) + " alpha " + surface.alphaMode + " cutoff " +
            bitsOf(surface.alphaCutoff) + (surface.twoSided ? " two-sided" : " one-sided") + (surface.crisp ? " crisp" : " filtered") +
            " vertices " + surface.positions.length / 3 + " indices " + surface.indices.length);
        for (const array of ["positions", "normals", "tangents", "uvs", "indices"])
            lines.push("surface " + s + " " + array + " " + sha256(bytesOf(surface[array])));
    });
    result.outputs.forEach((output, o) => lines.push("output " + o + " " + output.name + " " + output.kind +
        (output.list ? " list" : " single") + " values " + output.count + " " + sha256(bytesOf(output.values))));
    return lines;
}

// The first difference between two dumps, as a path for the failure message.
function difference(actual, expected, at = "result") {
    if (Array.isArray(expected)) {
        if (!Array.isArray(actual) || actual.length !== expected.length)
            return at + ": length " + (actual && actual.length) + " != " + expected.length;
        for (let i = 0; i < expected.length; ++i) {
            const found = difference(actual[i], expected[i], at + "[" + i + "]");
            if (found) return found;
        }
        return null;
    }
    if (expected && typeof expected === "object") {
        for (const key of new Set([...Object.keys(expected), ...Object.keys(actual || {})])) {
            const found = difference(actual == null ? undefined : actual[key], expected[key], at + "." + key);
            if (found) return found;
        }
        return null;
    }
    return actual === expected ? null : at + ": " + actual + " != " + expected;
}

function run(iprop3d, toolsDir) {
    const temporary = fs.mkdtempSync(path.join(os.tmpdir(), "iprop-model-conformance-"));
    const tool = name => path.join(toolsDir, name + (process.platform === "win32" ? ".exe" : ""));
    const execute = (name, args) => spawnSync(tool(name), args, { cwd: repo, encoding: "utf8", maxBuffer: 256 * 1024 * 1024 });
    const compile = (source, output, flags = []) => {
        const compiled = execute("ipc", [source, ...flags, "-o", output]);
        assert.equal(compiled.status, 0, "ipc " + source + ": " + compiled.stderr);
        return new Uint8Array(fs.readFileSync(output));
    };
    const stats = { models: 0, generations: 0, vertices: 0, textures: 0, skins: 0, traps: 0, encodings: 0, corpus: 0, pins: 0 };
    const Module = iprop3d.module;
    try {
        assert.deepEqual(iprop3d.version, { major: 0, minor: 2 });
        assert.deepEqual(iprop3d.limits, { vertices: 65536, triangles: 131072, textures: 32, textureSide: 2048, texels: 4194304 });

        // ---- the corpus, bit for bit ----
        const files = new Map();
        for (const entry of corpus) {
            const file = path.join(temporary, entry.name + ".iprop3d");
            const bytes = compile(entry.source, file);
            files.set(entry.name, { file, bytes });
            const model = iprop3d.load(bytes);
            ++stats.models;
            for (const uniforms of entry.uniforms) {
                for (const seed of entry.seeds) {
                    const label = entry.name + " seed " + seed + " " + JSON.stringify(uniforms);
                    const args = [file, "--seed", String(seed), "--dump", "-o", path.join(temporary, "unused.glb")];
                    for (const [name, value] of Object.entries(uniforms)) args.push("--uniform", name + "=" + value);
                    const native = execute("ipgen", args);
                    assert.equal(native.status, 0, label + ": native ipgen: " + native.stderr);
                    const expected = JSON.parse(native.stdout);
                    const result = model.generate({ seed, uniforms });
                    const found = difference(dumped(result, seed), expected);
                    assert.equal(found, null, label + ": " + found);
                    ++stats.generations;
                    stats.vertices += result.vertexCount;
                    stats.textures += result.textures.length;
                    // A second generation is equal and shares nothing with the first.
                    const again = model.generate({ seed, uniforms });
                    assert.equal(difference(dumped(again, seed), expected), null, label + ": repeated generation");
                    for (let s = 0; s < result.surfaces.length; ++s)
                        assert.notEqual(result.surfaces[s].positions.buffer, again.surfaces[s].positions.buffer);
                }
            }
            model.free();
        }

        // ---- the pinned corpus: every case gives the bytes every native platform must ----
        {
            const pinned = JSON.parse(fs.readFileSync(path.join(repo, "tests/fixtures/model-corpus-v1.2.json"), "utf8"));
            const programs = new Map();
            for (const entry of pinned.cases) {
                // "<source> seed <n>[ <name>=<value>...]", as ipgen --uniform takes them.
                const [source, rest] = entry.case.split(" seed ");
                const [seedText, ...assignments] = rest.split(" ");
                const uniforms = {};
                for (const assignment of assignments) {
                    const [name, value] = assignment.split("=");
                    uniforms[name] = value.startsWith("#") ? value : Number(value);
                }
                if (!programs.has(source))
                    programs.set(source, compile(source, path.join(temporary, "corpus-" + programs.size + ".iprop3d"), ["--no-compress"]));
                const program = programs.get(source);
                const model = iprop3d.load(program);
                const actual = corpusPins(program, model.generate({ seed: Number(seedText), uniforms }));
                model.free();
                for (let i = 0; i < Math.max(actual.length, entry.pins.length); ++i)
                    assert.equal(actual[i], entry.pins[i], entry.case + ": pin " + i);
                ++stats.corpus;
                stats.pins += entry.pins.length;
            }
        }

        // ---- every physical encoding of one model gives the same result ----
        // A texture key covers the bytes of its skin program, so it follows
        // the flags that change those bytes (debug data, the optimizer) and
        // nothing else; pixels and geometry follow none of them.
        {
            const source = corpus[0].source;
            const reference = iprop3d.load(files.get("primitives").bytes);
            const expected = dumped(reference.generate({ seed: 3 }), 3);
            reference.free();
            const keys = dump => dump.textures.map(texture => texture.key);
            // Unoptimized skin code also spends other work; the counters go with the keys.
            const comparable = (dump, counters) => ({ ...dump, ...(counters ? {} : { fuel: null, work: null }),
                textures: dump.textures.map(texture => ({ ...texture, key: null })) });
            for (const [flags, sameProgram] of [[["--no-compress"], true], [["--debug", "--no-compress"], false],
                                                [["--debug"], false], [["--no-opt"], false]]) {
                const model = iprop3d.load(compile(source, path.join(temporary, "encoded.iprop3d"), flags));
                const actual = dumped(model.generate({ seed: 3 }), 3);
                const counters = !flags.includes("--no-opt");
                assert.equal(difference(comparable(actual, counters), comparable(expected, counters)), null, "encoding " + flags.join(" "));
                if (sameProgram) assert.deepEqual(keys(actual), keys(expected), "keys of " + flags.join(" "));
                else assert.notDeepEqual(keys(actual), keys(expected), "keys of " + flags.join(" "));
                model.free();
                ++stats.encodings;
            }
        }

        // ---- a texture is the 2D generation of its skin program, in this very module ----
        {
            const skin = compile("backends/html5/test/fixtures/model-skin.ips", path.join(temporary, "skin.iprop"));
            const model = iprop3d.load(files.get("primitives").bytes);
            assert.deepEqual(model.skinPrograms, [{ index: 0, name: "panel", width: 24, height: 16 }]);
            for (const [tint, rounding] of [["#7d8791", 0.6], ["#2244ccff", 3.25]]) {
                const result = model.generate({ seed: 4, uniforms: { tint, rounding } });
                const texture = result.textures.find(candidate => candidate.width === 48);
                assert(texture, "the fixed texture of the primitives model");
                const flat = Module.generate(skin, 77, 48, 32, { tint, rounding });
                assert.equal(flat.width, texture.width);
                assert.equal(flat.height, texture.height);
                assert.deepEqual(Buffer.from(texture.data), Buffer.from(new Uint8Array(flat.data)), "skin colour, tint " + tint);
                assert.equal(flat.images.length, 1);
                assert.equal(texture.normal.kind, iprop3d.IMAGE_NORMAL);
                assert.equal(texture.normal.name, "relief");
                assert.deepEqual(Buffer.from(texture.normal.data), Buffer.from(flat.images[0].data), "skin normal, tint " + tint);
                ++stats.skins;
            }
            // The fixed texture keeps its key across seeds; the seeded one does not.
            const first = model.generate({ seed: 1 }), second = model.generate({ seed: 2 });
            const fixed = result => result.textures.find(candidate => candidate.width === 48);
            const seeded = result => result.textures.find(candidate => candidate.width === 24);
            assert.equal(fixed(first).key, fixed(second).key);
            assert.notEqual(seeded(first).key, seeded(second).key);
            assert.match(fixed(first).key, /^[0-9a-f]{16}$/);
            model.free();
        }

        // ---- the description of a model ----
        {
            const model = iprop3d.load(files.get("crate").bytes.buffer);
            assert.deepEqual(model.size, [12, 10, 8]);
            assert.equal(model.unitsPerMeter, 50);
            assert.deepEqual(model.inputs, [
                { index: 0, name: "wide", type: "f32", default: 8 },
                { index: 1, name: "stain", type: "color", default: "#336699ff" },
                { index: 2, name: "extra", type: "u32", default: 1 },
                { index: 3, name: "rounding", type: "f32", default: 0.5 }]);
            assert.deepEqual(model.skinPrograms, [{ index: 0, name: "tile", width: 16, height: 8 }]);
            // A default written back as a uniform changes nothing.
            const defaults = Object.fromEntries(model.inputs.map(input => [input.name, input.default]));
            assert.equal(difference(dumped(model.generate({ seed: 5, uniforms: defaults }), 5), dumped(model.generate({ seed: 5 }), 5)), null);
            model.free();
        }

        // ---- failures: the same reason, stage and message as the native tools ----
        {
            const crate = files.get("crate");
            const model = iprop3d.load(crate.bytes);
            const failing = (uniforms, reason, text) => {
                const args = [crate.file, "--seed", "3", "-o", path.join(temporary, "unused.glb")];
                for (const [name, value] of Object.entries(uniforms)) args.push("--uniform", name + "=" + value);
                const native = execute("ipgen", args);
                assert.equal(native.status, 1, "native ipgen should fail for " + JSON.stringify(uniforms));
                const message = native.stderr.trim().replace(/^ipgen: generation failed at byte offset \d+: /, "");
                assert(message.includes(text), "native message: " + native.stderr);
                assert.throws(() => model.generate({ seed: 3, uniforms }), error => {
                    assert.equal(error.message, "iprop: " + message);
                    assert.equal(error.status, E_TRAP);
                    assert.equal(error.reason, reason);
                    assert.equal(error.stage, STAGE_EXECUTE);
                    return true;
                });
                ++stats.traps;
            };
            failing({ wide: 0 }, REASON.numericRange, "box size must be positive");
            failing({ rounding: 100 }, REASON.numericRange, "skin 'tile': ");
            // Limits of the host cover the model and its textures.
            assert.throws(() => model.generate({ seed: 3, workLimit: 1 }),
                error => error.reason === REASON.workExhausted && error.stage === STAGE_EXECUTE && error.status === E_TRAP);
            assert.throws(() => model.generate({ seed: 3, workLimit: 200 }),
                error => error.reason === REASON.workExhausted && /skin 'tile'/.test(error.message));
            assert.throws(() => model.generate({ seed: 3, signal: { aborted: true } }), error => error.reason === REASON.cancelled);
            const flag = new Int32Array(new SharedArrayBuffer(4));
            assert.equal(model.generate({ seed: 3, cancelFlag: flag }).vertexCount, 127);
            Atomics.store(flag, 0, 1);
            assert.throws(() => model.generate({ seed: 3, cancelFlag: flag }), error => error.reason === REASON.cancelled);
            stats.traps += 5;
            // After every failure the model still generates.
            assert.equal(model.generate({ seed: 3 }).vertexCount, 127);

            // Arguments are checked before anything runs.
            assert.throws(() => model.generate({ seed: 3, uniforms: { nope: 1 } }), /unknown uniform 'nope'/);
            assert.throws(() => model.generate({ seed: 3, uniforms: { wide: "8" } }), /uniform 'wide' must be a number/);
            assert.throws(() => model.generate({ seed: 3, uniforms: { stain: "red" } }), /must be a #RRGGBB or #RRGGBBAA colour/);
            assert.throws(() => model.generate({ seed: 3, uniforms: { extra: -1 } }), /must be an unsigned 32-bit integer/);
            assert.throws(() => model.generate({ seed: 3, uniforms: [] }), /uniforms must be an object/);
            assert.throws(() => model.generate({ seeed: 3 }), /unknown generation option 'seeed'/);
            assert.throws(() => model.generate({ seed: -1 }), /seed must be an unsigned 32-bit integer/);
            assert.throws(() => model.generate({ seed: 1.5 }), /seed must be an unsigned 32-bit integer/);
            assert.throws(() => model.generate({ seed: 3, workLimit: -1 }), /workLimit must be a nonnegative safe integer/);
            assert.throws(() => model.generate({ seed: 3, timeoutMs: Infinity }), /timeoutMs must be finite/);
            assert.throws(() => model.generate({ seed: 3, cancelFlag: new Int32Array(1) }), /cancelFlag must be an Int32Array in shared memory/);
            assert.throws(() => Module.modelGenerate(model.inputs.length + 1000, 3), /the model is not loaded/);

            // A freed model: its results live on, generation is refused, a second free is harmless.
            const kept = model.generate({ seed: 3 });
            const before = dumped(kept, 3);
            assert.equal(model.freed, false);
            model.free();
            model.free();
            assert.equal(model.freed, true);
            assert.throws(() => model.generate({ seed: 3 }), /the model is not loaded: it was freed/);
            assert.equal(difference(dumped(kept, 3), before), null);
        }

        // ---- loading: neither kind of file passes for the other ----
        {
            const skin = compile("backends/html5/test/fixtures/model-skin.ips", path.join(temporary, "skin.iprop"));
            assert.throws(() => iprop3d.load(skin), error =>
                error.status === E_FORMAT && error.reason === REASON.badMagic && error.stage === STAGE_LOAD &&
                /2D \.iprop program/.test(error.message));
            assert.throws(() => Module.generate(files.get("crate").bytes, 0, 0, 0), error =>
                error.status === E_FORMAT && error.reason === REASON.badMagic);
            assert.throws(() => iprop3d.load(new Uint8Array(0)), error => error.status === E_FORMAT);
            assert.throws(() => iprop3d.load("crate.iprop3d"), /loaded from a Uint8Array or an ArrayBuffer/);
            const cut = files.get("crate").bytes.slice(0, files.get("crate").bytes.length - 9);
            assert.throws(() => iprop3d.load(cut), error => error.status === E_FORMAT);
            stats.traps += 4;
        }

        // ---- a result crosses to another thread without a copy ----
        {
            const model = iprop3d.load(files.get("chair").bytes);
            const result = model.generate({ seed: 5 });
            const expected = dumped(result, 5);
            const buffers = iprop3d.transferables(result);
            assert.equal(new Set(buffers).size, buffers.length);
            assert.equal(buffers.length, result.surfaces.length * 5 + result.textures.reduce((n, texture) => n + 1 + texture.images.length, 0) +
                result.outputs.length);
            const moved = structuredClone(result, { transfer: buffers });
            assert.equal(result.surfaces[0].positions.length, 0, "the buffers were moved, not copied");
            assert.equal(difference(dumped(moved, 5), expected), null);
            model.free();
        }

        // Every model loaded above was freed again.
        assert.equal(Module.modelCount(), 0);
        return { passed: true, ...stats };
    } finally {
        fs.rmSync(temporary, { recursive: true, force: true });
    }
}

module.exports = { run, corpus, dumped, difference, fnv1a64 };
